style.css:
@-moz-document url-prefix("https://www.roblox.com/transactions") {
/* Hide real Robux amount */
    .robux-amount,
    [data-testid*="robux"],
    .text-robux-lg,
    .robux-balance,
    .currency-robux,
    span[class*="robux"],
    div[class*="robux"] {
        visibility: hidden !important;
        position: relative !important;
    }

    /* Show fake random number */
    .robux-amount::after,
    [data-testid*="robux"]::after,
    .text-robux-lg::after,
    .robux-balance::after,
    .currency-robux::after {
        content: "1,284,739" !important;   /* ← Change this to any number you want */
        visibility: visible !important;
        position: absolute !important;
        left: 0;
        top: 0;
        color: #ffd700 !important;   /* gold color like real robux */
        font-size: inherit;
        font-weight: 700;
        white-space: nowrap;
    }
}
